import sys
sys.setrecursionlimit(2000000)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    m = int(input_data[1])

    grid = []
    idx = 2
    for _ in range(n):
        grid.append(input_data[idx])
        idx += 1

    # Map characters to sequence indices: D->0, I->1, M->2, A->3
    char_to_idx = {'D': 0, 'I': 1, 'M': 2, 'A': 3}

    # dp[r][c] stores the max length of path ending at (r, c)
    # We compute this using memoization with DFS
    # States: 0 = unvisited, 1 = visiting (cycle detection), 2 = visited

    state = [[0] * m for _ in range(n)]
    dp = [[0] * m for _ in range(n)]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(r, c):
        if state[r][c] == 1:
            return float('inf')  # Cycle detected
        if state[r][c] == 2:
            return dp[r][c]

        state[r][c] = 1
        current_char = grid[r][c]
        current_seq_idx = char_to_idx[current_char]
        next_seq_idx = (current_seq_idx + 1) % 4

        max_next_len = 0
        found_next = False

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                neighbor_char = grid[nr][nc]
                neighbor_seq_idx = char_to_idx[neighbor_char]

                if neighbor_seq_idx == next_seq_idx:
                    res = dfs(nr, nc)
                    if res == float('inf'):
                        return float('inf')
                    if res + 1 > max_next_len:
                        max_next_len = res + 1
                    found_next = True

        # If we found a valid next step, the length is max_next_len + 1 (including current)
        # But wait, the logic needs to be: 
        # The value at a node is 1 + max(value of next nodes).
        # However, we want to count full "DIMA" cycles.
        # Let's redefine: dp[r][c] = length of the longest path starting at (r,c)
        # If we are at 'D', and we go D->I->M->A->D..., the length counts steps.
        # A full DIMA is 4 steps.
        # Actually, let's count the number of characters in the path.
        # If path is D-I-M-A-D-I-M-A, length is 8, which means 2 DIMAs.
        # If no next move is possible, length is 1 (just the current char).

        if not found_next:
            dp[r][c] = 1
        else:
            dp[r][c] = max_next_len + 1

        state[r][c] = 2
        return dp[r][c]

    infinite_found = False
    max_len = 0

    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'D':
                if state[r][c] == 0:
                    res = dfs(r, c)
                    if res == float('inf'):
                        infinite_found = True
                    else:
                        if res > max_len:
                            max_len = res

    if infinite_found:
        print("Poor Inna!")
    elif max_len < 4:
        print("Poor Dima!")
    else:
        print(max_len // 4)

if __name__ == "__main__":
    main()
